#include "engine.hpp"
#include <iostream>
#include <cmath>
using namespace uaa;
void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
int main(int argc,char** argv){try{Engine e(argv[1],argv[2]);e.createBase("LOSSES",0,0);e.state["nextUfo"]=100000.;auto design=e.gameset();auto money=e.state["money"];auto stock=e.state["stock"];auto n=e.state["craft"].size();check(e.damageAircraft(0,10).ok&&e.state["craft"].size()==n,"Damaged but surviving aircraft stays available for repair");e.state["craft"][0]["hull"]=31.;e.state["ufos"].push_back({{"type","SINGLE_SEAT_CIRCULAR"},{"lat",0.},{"lon",0.},{"hull",10000.},{"spawned",0.},{"expires",48.},{"environment","AIR"}});e.rng.seed(1);check(e.intercept(0,0).ok&&e.state["craft"].size()==n-1&&e.state["aircraftLosses"].size()==1,"Enemy fire can destroy a fighter and remove it immediately");check(e.state["money"]==money&&e.state["stock"]==stock&&e.gameset()==design,"Aircraft loss gives no refund and preserves manufacture catalogue");
 Engine t(argv[1],std::filesystem::path(argv[2])/"transport");t.createBase("TRANSPORT",0,0);t.state["nextUfo"]=100000.;int pilot=-1,nav=-1;std::vector<int> squad;for(int i=0;i<int(t.state["personnel"].size());++i){auto role=t.state["personnel"][i]["role"];if(role=="pilot"&&pilot<0)pilot=i;if(role=="navigator"&&nav<0)nav=i;if(role=="soldier"&&squad.size()<2)squad.push_back(i);}check(t.assignCrew(1,"pilot",pilot).ok&&t.assignCrew(1,"navigator",nav).ok,"Assign transport crew");for(int p:squad)check(t.toggleTransportSoldier(1,p).ok,"Assign passengers");t.state["stock"]["underwater-robot"]=1;t.state["stock"]["compressed-air-cannon"]=1;t.state["stock"]["air-round"]=20;check(t.setTransportRobot(1,true,"AIR").ok&&t.departTransport(1).ok,"Load soldiers and robot into transport");auto boardedStock=t.state["stock"];auto living=t.state["personnel"][pilot];check(t.damageAircraft(1,1000).ok&&t.state["craft"].size()==2,"Destroyed amphibious transport disappears from fleet");for(int p:squad)check(t.state["personnel"][p]["dead"]==true&&t.state["personnel"][p]["health"]==0&&t.state["personnel"][p]["salary"]==0&&!t.equipSoldier(p,"primaryWeapon","pistol").ok,"Every onboard soldier dies and cannot recover equipment");check(t.state["aircraftLosses"][0]["tankLost"]==true&&t.state["aircraftLosses"][0]["craft"]["robotHealth"]==0&&t.state["stock"]==boardedStock,"Onboard tank, modules and ammunition are lost without being returned");check(t.state["personnel"][pilot]==living,"Unspecified crew policy is not changed by passenger casualty handling");t.save(1);Engine reload(argv[1],std::filesystem::path(argv[2])/"transport");check(reload.load(1).ok&&reload.state["craft"].size()==2&&reload.state["personnel"][squad[0]]["dead"]==true,"Losses and deaths survive save/load");check(reload.damageAircraft(1,1000).ok&&reload.state["craft"].size()==1,"AWACS destruction follows the same fleet removal rule");check(reload.damageAircraft(0,1000).ok&&reload.state["craft"].empty(),"Final aircraft can be lost without leaving a selectable ghost");for(auto key:{"iron","plastics","electronics","glass"})reload.state["stock"][key]=10000;reload.state["money"]=100000000LL;check(reload.record("units","fighter")&&reload.manufactureQuote("units","fighter")["ok"].get<bool>(),"New fighter manufacture remains available after total fleet loss");
 Engine old(argv[1],std::filesystem::path(argv[2])/"legacy");old.createBase("LEGACY",0,0);old.state["craft"][0]["hull"]=0.;old.state["craft"][0]["serviceReady"]=1.;old.save(1);Engine migrated(argv[1],std::filesystem::path(argv[2])/"legacy");check(migrated.load(1).ok&&migrated.state["craft"].size()==2,"Legacy zero-hull aircraft is removed when loaded");migrated.advance(2);check(migrated.state["craft"].size()==2,"Pending service cannot resurrect destroyed aircraft");std::cout<<"PASS: real fighter shootdown, all aircraft types, no refund, living damage, passenger fatalities, tank/cargo loss, persistence, legacy cleanup and manufacture retained\n";return 0;}catch(const std::exception& ex){std::cerr<<ex.what()<<'\n';return 1;}}
